INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45511, 'Jeremiah 33:24', 'Jeremiah', 33, 24, '”آيا تا د خلقو خبرو ته غوږ نۀ دے نيولے چې هغوئ وائى، مالِک خُدائ اوس هغه دوه قومونه رد کړى دى کوم چې اول هغۀ غوره کړى وُو؟ نو هغوئ زما د قوم سپکوالے کوى او د يو قوم په حيثيت يې نۀ منى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_24.mp3', '', 1761754199, 1761754199),
(45512, 'Jeremiah 33:25', 'Jeremiah', 33, 25, 'خو مالِک خُدائ داسې فرمائى چې، کۀ چرې ما د ورځې او د شپې سره لوظ نۀ وو کړے او د زمکې او آسمان نظام مې نۀ وو جوړ کړے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_25.mp3', '', 1761754199, 1761754199),
(45513, 'Jeremiah 33:26', 'Jeremiah', 33, 26, 'نو بيا به زۀ د يعقوب او د خپل خِدمتګار داؤد اولاد نامنظور کړم، او نۀ به د يعقوب او د داؤد د اولاد نه څوک خوښ کړم چې د اِبراهيم، اِسحاق او يعقوب په اولاد حکومت وکړى. ځکه چې زۀ به هغوئ د غلامۍ نه واپس راولم او په هغوئ به رحم وکړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_26.mp3', '', 1761754199, 1761754199),
(45514, 'Daniel 7:1', 'Daniel', 7, 1, 'د بابل د بادشاه بيلشضر د بادشاهۍ په اول کال، دانيال چې کله په خپل کټ کښې پروت وو نو هغۀ خوب وليدو او په خوب کښې د هغۀ په خيالونو کښې يوه رويا راغله. هغۀ هغه څۀ وليکل کوم چې هغۀ په خوب کښې وليدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_1.mp3', '', 1761754199, 1761754199),
(45515, 'Daniel 7:2', 'Daniel', 7, 2, 'دانيال وفرمائيل چې، ”په هغه شپه ما په رويا کښې وليدل چې هلته زما په وړاندې د آسمان هواګانې د څلورو خواو نه د سمندر په مخ په تېزه لګېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_2.mp3', '', 1761754199, 1761754199),
(45516, 'Daniel 7:3', 'Daniel', 7, 3, 'نو څلور غټ ځناور، چې د يو بل نه مختلف وُو، د سمندر نه بهر راووتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_3.mp3', '', 1761754199, 1761754199),
(45517, 'Daniel 7:4', 'Daniel', 7, 4, 'اولنے د زمرى په شان وو، او د باز غوندې وزرې يې وې. ما تر هغې پورې ورته کتل ترڅو چې يې وزرې پرې کړے شوې او ودرولے شو او بيا دا لکه د انسان په شان په زمکه په دوو پښو ودرېدلو، او انسانى سوچ ورته ورکړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_4.mp3', '', 1761754199, 1761754199),
(45518, 'Daniel 7:5', 'Daniel', 7, 5, 'نو بيا زما په وړاندې ما دوېم ځناور وليدو، کوم چې د مېلو په شان ښکارېدو. دا په خپل يو طرف باندې اوچت کړے شو، او دۀ درې پښتۍ په خپله خولۀ کښې د غاښونو په مينځ کښې نيولې وې. هغۀ ته وئيل کېدۀ، پاڅه او په غوښو ځان موړ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_5.mp3', '', 1761754199, 1761754199),
(45519, 'Daniel 7:6', 'Daniel', 7, 6, 'د دې نه وروستو، ما يو بل ځناور وليدو، هغه لکه د پړانګ په شان وو. او د دۀ په شا لکه د مارغۀ په شان څلور وزرې وې. د دې ځناور څلور سرونه وُو، او دۀ ته يې د حکومت کولو اختيار ورکړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_6.mp3', '', 1761754199, 1761754199),
(45520, 'Daniel 7:7', 'Daniel', 7, 7, 'د دې نه وروستو د شپې ما په خپله رويا کښې څلورم ځناور وليدو چې خطرناک او يروونکے او ډېر طاقتور وو. د اوسپنې غټ غاښونه يې وُو او خپل ښکار به يې په هغې ريچې ريچې کړو او تير به يې کړو او څۀ به چې ترې نه پاتې شو نو هغه به يې د خپلو پښو لاندې کړو. هغه د نورو ټولو ځناورو نه کوم چې مخکښې وُو مختلف وو، او د هغۀ لس ښکرونه وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_7.mp3', '', 1761754199, 1761754199),
(45521, 'Daniel 7:8', 'Daniel', 7, 8, 'کله چې ما د هغۀ د ښکرونو په حقله سوچ کولو، نو هلته زما د وړاندې يو بل ورکوټے ښکر د هغوئ په مينځ کښې ښکاره شو، او درې وړومبى ښکرونه د هغۀ په وړاندې راوويستلے شول. د هغه ښکر لکه د انسان د سترګو په شان سترګې وې او په خولۀ باندې يې په بې‌پرواهۍ سره لافې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_8.mp3', '', 1761754199, 1761754199),
(45522, 'Daniel 7:9', 'Daniel', 7, 9, 'کله چې ما ورته کتل نو تختونه په خپل ځائ باندې ولګولے شُو، او ازلى ذات په خپل تخت کښېناستو. د هغۀ جامې لکه د واورې په شان سپينې وې، او د هغۀ د سر وېښتۀ لکه د سپينې وړۍ په شان وُو. او هغه د اور په تخت باندې کښېناستو او د پايو نه يې د اور شُغلې ختلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_9.mp3', '', 1761754199, 1761754199),
(45523, 'Daniel 7:10', 'Daniel', 7, 10, 'او د هغۀ د حضور نه د اور درياب راوتلو او د هغۀ په وړاندې روان وو. په زرګونو زرګونو د هغۀ خِدمت له راغلل، او په لکونو هستيانې د هغۀ په وړاندې ودرېدلې. بيا د عدالت دپاره دربار کولاو شو، او کتابونه کولاو کړے شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_10.mp3', '', 1761754199, 1761754199),
(45524, 'Daniel 7:11', 'Daniel', 7, 11, 'ورته مې هم هغه شان کتل ځکه چې هغه ورکوټے ښکر د کبر نه ډکې خبرې کولې. تر هغې پورې مې ورته کتل چې هغه څلورم ځناور مړ کړے شو او د دۀ لاش تباه او بَل شوى اور ته وغورزولے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_11.mp3', '', 1761754199, 1761754199),
(45525, 'Daniel 7:12', 'Daniel', 7, 12, 'د هغه نورو درېو واړو ځناورو نه قدرت واخستلے شو، خو هغوئ ته د لږ وخت دپاره د ژوندى پاتې کېدلو اجازت مِلاو شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_12.mp3', '', 1761754199, 1761754199),
(45526, 'Daniel 7:13', 'Daniel', 7, 13, 'نو په هم هغه شپه کښې ما په خپله رويا کښې وليدل، چې هلته زما په وړاندې يو کس لکه د اِبن آدم په شان وو، چې د آسمان د وريځو سره راروان وو. او هغه ازلى ذات ته ورورسېدو او د هغۀ حضور ته حاضر کړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_13.mp3', '', 1761754199, 1761754199),
(45527, 'Daniel 7:14', 'Daniel', 7, 14, 'هغۀ ته اختيار، جلال او شاهى طاقت ورکړے شو، د ټولو قومونو، ذاتونو او ژبو خلقو د هغۀ عبادت وکړو. د هغۀ بادشاهى ابدى او نۀ ختمېدونکې ده، د هغۀ بادشاهى به هيڅ کله تباه نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_14.mp3', '', 1761754199, 1761754199),
(45528, 'Daniel 7:15', 'Daniel', 7, 15, 'زۀ دانيال، د هغه هر څۀ په حقله پرېشانه وم څۀ چې ما ليدلى وُو، او زما رويا زۀ ويرولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_15.mp3', '', 1761754199, 1761754199),
(45529, 'Daniel 7:16', 'Daniel', 7, 16, 'نو بيا زۀ هغه ولاړو کسانو ته چې هلته تخت سره نزدې وُو يو له ورغلم او تپوس مې ترې نه وکړو چې د دې هر څۀ مطلب څۀ دے. نو هغۀ ما ته د دې تعبير څۀ داسې وکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_16.mp3', '', 1761754199, 1761754199),
(45530, 'Daniel 7:17', 'Daniel', 7, 17, 'دا څلور ځناور څلور بادشاهۍ دى چې د زمکې نه به راوچتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_17.mp3', '', 1761754199, 1761754199),
(45531, 'Daniel 7:18', 'Daniel', 7, 18, 'خو په آخر کښې به د خُدائ تعالىٰ مقدسو خلقو ته بادشاهى مِلاو شى، او هغوئ به په هغې باندې تر ابده پورې بادشاهى کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_18.mp3', '', 1761754199, 1761754199),
(45532, 'Daniel 7:19', 'Daniel', 7, 19, 'نو بيا ما غوښتل چې د څلورم ځناور په حقله صحيح مطلب باندې ځان پوهه کړم، کوم چې د نورو ټولو نه مختلف او يروونکے وو. او غاښونه يې د اوسپنې او د پښو پنجې يې د زېړو وې، هغه ځناور چې خپل ښکارونه يې ريچې ريچې کړل او تير يې کړل او څۀ چې ترې نه پاتې شول هغه يې د پښو لاندې کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_19.mp3', '', 1761754199, 1761754199),
(45533, 'Daniel 7:20', 'Daniel', 7, 20, 'ما هم غوښتل چې د هغۀ په سر د هغه لسو ښکرونو په حقله معلومات حاصل کړم، د هغه بل ښکر په حقله کوم چې راوختلو، د کوم د راختلو نه مخکښې چې هغه درې وغورزېدل، هغه ښکر چې د نورو نه بيا غټ ښکارېدو او چې سترګې يې د انسان په شان وې، او د دې خولې د کبر خبرې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_20.mp3', '', 1761754199, 1761754199),
(45534, 'Daniel 7:21', 'Daniel', 7, 21, 'کله چې ما دا هر څۀ کتل، نو دې ښکر د مقدسينو خلاف جنګ وکړو او هغوئ ته يې شکست ورکولو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_21.mp3', '', 1761754199, 1761754199),
(45535, 'Daniel 7:22', 'Daniel', 7, 22, 'ترڅو چې هغه ازلى ذات راغلو او د خُدائ تعالىٰ د مقدسينو په حق کښې يې د عدالت اعلان وکړو. او بيا هغه وخت راغلو چې هغوئ ته بادشاهى مِلاو شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_22.mp3', '', 1761754199, 1761754199),
(45536, 'Daniel 7:23', 'Daniel', 7, 23, 'نو بيا هغۀ ما ته ووئيل چې، دا څلورم ځناور هغه د دُنيا څلورمه بادشاهى ده کومه چې به په زمکه راښکاره شى. دا به د نورو ټولو بادشاهتونو نه مختلفه وى او دا به ټوله زمکه تيره کړى، او د پښو لاندې او ريچې ريچې به يې کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_23.mp3', '', 1761754199, 1761754199),
(45537, 'Daniel 7:24', 'Daniel', 7, 24, 'هغه لس ښکرونه لس بادشاهان دى څوک چې به د دې بادشاهۍ نه راشى. د دوئ نه وروستو به يو بل بادشاه پېدا شى، هغه به د مخکښېنو نه مختلف وى، هغه به درې بادشاهان ختم کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_24.mp3', '', 1761754199, 1761754199),
(45538, 'Daniel 7:25', 'Daniel', 7, 25, 'هغه به د خُدائ تعالىٰ خلاف خبرې کوى او د هغۀ په مقدسينو به ظلم وکړى، شريعت او د اخترونو مقرر وخت د بدلولو کوشش به وکړى. مقدسين به هغۀ ته د درې نيمو کالو دپاره حواله شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_25.mp3', '', 1761754199, 1761754199),
(45539, 'Daniel 7:26', 'Daniel', 7, 26, 'خو بيا به د هغۀ خلاف عدالت شروع شى، او د هغۀ نه به حکومت واخستلے شى او هغه به هم په مکمل توګه تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_26.mp3', '', 1761754199, 1761754199),
(45540, 'Daniel 7:27', 'Daniel', 7, 27, 'نو بيا به د آسمان لاندې د ټولو بادشاهتونو حکومت، طاقت او لوئى هغه ايماندارانو ته حواله شى چې د خُدائ تعالىٰ خلق دى. د هغۀ بادشاهى به ابدى وى، او ټول حکمرانان به د هغۀ عبادت او تابعدارى وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_27.mp3', '', 1761754199, 1761754199),
(45541, 'Daniel 7:28', 'Daniel', 7, 28, 'دا خبره دلته ختمه شوه. زۀ دانيال په خپلو خيالونو کښې پرېشانه وم او زما مخ د يرې نه تک زېړ وو، خو دا خبره ما خپل ځان سره محفوظه وساتله.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel7_verse_28.mp3', '', 1761754199, 1761754199),
(45542, 'Deuteronomy 11:1', 'Deuteronomy', 11, 1, 'د خپل څښتن خدای سره مینه کوئ او تل د هغه د ټولو قوانینو څخه اطاعت کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_1.mp3', '', 1761754199, 1761754199),
(45543, 'Deuteronomy 11:2', 'Deuteronomy', 11, 2, 'نن ورځ دا په یاد ساتئ چې دا تاسو وئ، نه ستاسو اولادونه چې د خپل څښتن خدای اصلاح، د هغه لویي، خپل قوي مټ، ټول قدرت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_2.mp3', '', 1761754199, 1761754199),
(45544, 'Deuteronomy 11:3', 'Deuteronomy', 11, 3, 'او معجزې مو لیدلې دي. تاسو ولیدل چې هغه د مصر د پاچا فرعون او د هغه د ټول هېواد سره څه وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_3.mp3', '', 1761754199, 1761754199),
(45545, 'Deuteronomy 11:4', 'Deuteronomy', 11, 4, 'تاسو ولیدل چې څښتن څنګه د مصریانو لښکرې د هغوی د اسونو او جنګي ګاډیو سره تباه کړې او هغوی یې په داسې وخت کې په سره بحیره کې ډوب کړل کله چې تاسو یې تعقیبولئ. څښتن هغوی د داسې تباهۍ سره مخامخ کړل چې تر اوسه پورې دوام لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_4.mp3', '', 1761754199, 1761754199),
(45546, 'Deuteronomy 11:5', 'Deuteronomy', 11, 5, 'تاسو پوهېږئ مخکې له دې چې تاسو دلته راورسېدلئ، څښتن ستاسو دپاره په دښته کې څه وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_5.mp3', '', 1761754199, 1761754199),
(45547, 'Deuteronomy 11:6', 'Deuteronomy', 11, 6, 'در په یاد کړئ چې هغه د روبین د قبیلې د الیاب په زامنو یعنې په داتان او ابیرام باندې څه وکړل. د ټولو خلکو په مخکې ځمکه پرانیستل شوه او هغوی یې د خپلو کورنیو، خېمو او ټولو غلامانو او حیواناتو سره ژوندي تېر کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_6.mp3', '', 1761754199, 1761754199),
(45548, 'Deuteronomy 11:7', 'Deuteronomy', 11, 7, 'هو، تاسو هماغه خلک یئ چې دا ټول لوی لوی کارونه چې څښتن کړي دي، هغه مو لیدلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_7.mp3', '', 1761754199, 1761754199),
(45549, 'Deuteronomy 11:8', 'Deuteronomy', 11, 8, 'د هغو ټولو قوانینو اطاعت کوئ چې نن مې درکړل. نو بیا به د دې قوت پیدا کړئ چې د اردن د سیند څخه تېر شئ او هغه خاوره ونیسئ چې تاسو ورننوځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_8.mp3', '', 1761754199, 1761754199),
(45550, 'Deuteronomy 11:9', 'Deuteronomy', 11, 9, 'تاسو به په هغې غني او حاصلخېزه خاوره کې ډېره موده ژوند وکړئ چې څښتن یې د ورکولو وعده ستاسو د نیکونو او د هغوی د اولادې سره کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_9.mp3', '', 1761754199, 1761754199),
(45551, 'Deuteronomy 11:10', 'Deuteronomy', 11, 10, 'کومه خاوره چې تاسو یې اوس نیسئ د مصر د خاورې په شان نه ده چې مخکې په کې اوسېدلئ. تاسو چې کله هلته تخم کرلو، مجبور وئ چې پټیو ته د اوبو ورکولو دپاره ډېر زیار او زحمت وباسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_10.mp3', '', 1761754199, 1761754199),
(45552, 'Deuteronomy 11:11', 'Deuteronomy', 11, 11, 'خو هغه خاوره چې تاسو به ورننوځئ، هلته غرونه او درې دي او د باران په وسیله ورته اوبه ورکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_11.mp3', '', 1761754199, 1761754199),
(45553, 'Deuteronomy 11:12', 'Deuteronomy', 11, 12, 'ستاسو څښتن خدای په دې ځمکه باندې پام کوي او ټول کال هغه تر خپل نظر لاندې ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_12.mp3', '', 1761754199, 1761754199),
(45554, 'Deuteronomy 11:13', 'Deuteronomy', 11, 13, 'نو بیا د هغو امرونو اطاعت کوئ چې نن مې درکړل. د خپل څښتن خدای سره مینه کوئ او د زړه له کومي د هغه خدمت کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_13.mp3', '', 1761754199, 1761754199),
(45555, 'Deuteronomy 11:14', 'Deuteronomy', 11, 14, 'که چېرې داسې وکړئ، نو هغه به د اړتیا په وخت یعنې په مني او پسرلي کې ستاسو په ځمکه باندې باران ووروي، ترڅو تاسو ته غلې دانې، شراب او د زیتونو تېل درورسیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_14.mp3', '', 1761754199, 1761754199),
(45556, 'Deuteronomy 11:15', 'Deuteronomy', 11, 15, 'او حیواناتو ته به مو واښه ورورسیږي. هرڅومره خواړه چې غواړئ تاسو ته به درورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_15.mp3', '', 1761754199, 1761754199),
(45557, 'Deuteronomy 11:16', 'Deuteronomy', 11, 16, 'پام کوئ. که نه، نو تاسو به وغولېږئ او بې لارې به شئ او د نورو خدایانو عبادت به وکړئ او هغو ته به سجده وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_16.mp3', '', 1761754199, 1761754199),
(45558, 'Deuteronomy 11:17', 'Deuteronomy', 11, 17, 'که چېرې تاسو داسې وکړئ، نو څښتن به درباندې په قهر شي. هغه به درباندې باران ودروي، ستاسو ځمکه به وچه شي او فصلونه به په کې نه راشنه کیږي. که څه هم هغه ځمکه چې هغه یې تاسو ته درکوي ښه ده، خو تاسو به په کې زر مړه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_17.mp3', '', 1761754199, 1761754199),
(45559, 'Deuteronomy 11:18', 'Deuteronomy', 11, 18, 'دا قوانین په خپلو زړونو او فکرونو کې په یاد ساتئ او د هغو په هکله فکر کوئ. هغه ولیکئ او په خپلو مټو او تندیو باندې یې وتړئ چې د هغو په اطاعت کولو کې درسره مرسته وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_18.mp3', '', 1761754199, 1761754199),
(45560, 'Deuteronomy 11:19', 'Deuteronomy', 11, 19, 'هغه خپلو اولادونو ته ورزده کړئ. هر وخت د هغو په هکله خبرې کوئ، که په کور کې یئ یا په لاره روان یئ یا ارام کوئ یا کار کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_19.mp3', '', 1761754199, 1761754199),
(45561, 'Deuteronomy 11:20', 'Deuteronomy', 11, 20, 'دا قوانین د خپلو کورونو د دروازو په چوکاټونو او د خپلو ښارونو په دروازو باندې ولیکئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_20.mp3', '', 1761754199, 1761754199),
(45562, 'Deuteronomy 11:21', 'Deuteronomy', 11, 21, 'بیا به تاسو او ستاسو اولاده په هغه خاوره کې ډېره موده ژوند وکړئ چې څښتن ستاسو د نیکونو سره د هغې د ورکولو وعده کړې ده. ترڅو پورې چې ځمکه او اسمان وي، تاسو به هلته ژوند کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_21.mp3', '', 1761754199, 1761754199),
(45563, 'Deuteronomy 11:22', 'Deuteronomy', 11, 22, 'د هغو ټولو قوانینو څخه چې ما درکړي دي په وفادارۍ سره اطاعت کوئ. د خپل څښتن خدای سره مینه کوئ، د هغه هر امر په ځای کوئ او هغه ته وفادار اوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_22.mp3', '', 1761754199, 1761754199),
(45564, 'Deuteronomy 11:23', 'Deuteronomy', 11, 23, 'بیا به څښتن هغه ټول قومونه ستاسو له مخې څخه لېرې کړي او تاسو به د هغو قومونو ځمکه ونیسئ چې ستاسو څخه لوی او قوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_23.mp3', '', 1761754199, 1761754199),
(45565, 'Deuteronomy 11:24', 'Deuteronomy', 11, 24, 'په هرځای باندې چې تاسو قدم ږدئ هغه به ستاسو وي. ستاسو سیمه به د جنوبي دښتې څخه په شمال کې د لبنان تر غرونو پورې وغزیږي او د فرات د سیند څخه به چې په ختیځ کې دی، د مدیترانې تر بحیرې پورې چې په لوېدیځ کې ده وغزیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_24.mp3', '', 1761754199, 1761754199),
(45566, 'Deuteronomy 11:25', 'Deuteronomy', 11, 25, 'د هغې خاورې هرځای ته چې تاسو لاړ شئ، ستاسو څښتن خدای به د خپلې وعدې سره سم د هغو خلکو په زړونو کې وېره واچوي چې ستاسو څخه ووېریږي او هېڅوک به ونه شي کولای چې ستاسو په وړاندې ودریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_25.mp3', '', 1761754199, 1761754199),
(45567, 'Deuteronomy 11:26', 'Deuteronomy', 11, 26, 'زه نن تاسو ته دا موقع درکوم چې د څښتن څخه برکت غواړئ یا غواړئ چې لعنت درباندې وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_26.mp3', '', 1761754199, 1761754199),
(45568, 'Deuteronomy 11:27', 'Deuteronomy', 11, 27, 'که چېرې د خپل څښتن خدای د حکمونو څخه چې زه یې نن درکوم اطاعت وکړئ، برکت به ومومئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_27.mp3', '', 1761754199, 1761754199),
(45569, 'Deuteronomy 11:28', 'Deuteronomy', 11, 28, 'خو که چېرې د دغو حکمونو څخه سرغړونه وکړئ او د هغو نورو خدایانو عبادت وکړئ چې مخکې مو هېڅکله د هغو عبادت نه دی کړی، نو څښتن به درباندې لعنت ووایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_28.mp3', '', 1761754199, 1761754199),
(45570, 'Deuteronomy 11:29', 'Deuteronomy', 11, 29, 'کله چې څښتن تاسو هغې خاورې ته ورولي چې تاسو یې نیسئ، نو د جرزیم د غره څخه به د برکت اعلان وکړئ او د عیبال د غره څخه به د لعنت اعلان وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_29.mp3', '', 1761754199, 1761754199),
(45571, 'Deuteronomy 11:30', 'Deuteronomy', 11, 30, 'تاسو پوهېږئ چې دا دوه غرونه د اردن د سیند په لوېدیځ کې په هغې خاورې کې دي چې اوس د هغو کنعانیانو تر واکمنۍ لاندې ده چې د اردن په دره کې اوسیږي. دا غرونه د جلجال بلې خواته د موره سپېڅلو ونو ته نژدې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_30.mp3', '', 1761754199, 1761754199),
(45572, 'Deuteronomy 11:31', 'Deuteronomy', 11, 31, 'تاسو به زر د اردن د سیند څخه تېر شئ او هغه خاوره به ونیسئ چې ستاسو څښتن خدای یې درکوي. کله چې تاسو هغه خاوره ونیسئ او په کې اوسېږئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_31.mp3', '', 1761754199, 1761754199),
(45573, 'Deuteronomy 11:32', 'Deuteronomy', 11, 32, 'نو تاسو به په غور سره د هغو ټولو قوانینو اطاعت کوئ چې زه یې نن درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy11_verse_32.mp3', '', 1761754199, 1761754199),
(45574, 'Psalms 66:1', 'Psalms', 66, 1, 'ای د ټولې دنیا خلکو ووهئ د خوشحالۍ چیغې وکړئ صفت د خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_1.mp3', '', 1761754199, 1761754199),
(45575, 'Psalms 66:2', 'Psalms', 66, 2, 'سندرې وایئ د جلال تاسې د نوم د هغه ووایئ حمد او ثنا تاسې د هغه جلالي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_2.mp3', '', 1761754199, 1761754199),
(45576, 'Psalms 66:3', 'Psalms', 66, 3, 'خدای ته ووایئ چې کوې ته څومره هیبتناک کارونه څومره دی لوی ستا قدرت چې دښمنان د ستا له وېرې سجدې کړي تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_3.mp3', '', 1761754199, 1761754199),
(45577, 'Psalms 66:4', 'Psalms', 66, 4, 'د جهان ټول خلک دې کړي عبادت وایي سندرې د ستاینې تاته ستا په نامه باندې سندرې د ثنا وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_4.mp3', '', 1761754199, 1761754199),
(45578, 'Psalms 66:5', 'Psalms', 66, 5, 'راشئ او وګورئ چې خدای کړي دي د انسانانو په خاطر څه هیبتناک کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_5.mp3', '', 1761754199, 1761754199),
(45579, 'Psalms 66:6', 'Psalms', 66, 6, 'په وچه ځمکه یې بدله کړله سره بحیره زمونږ نیکونه په سیند واوختل په خپلو پښو نو کوم کارونه چې انجام کړل هغه په دې سبب مو هغه ځای کې خوشحالي وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_6.mp3', '', 1761754199, 1761754199),
(45580, 'Psalms 66:7', 'Psalms', 66, 7, 'پاچاهي په خپل قوت کړي تل ترتله په نورو قومونو خپل نظر ساتي راپورته نه شئ د هغه په ضد سرکښو خلکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_7.mp3', '', 1761754199, 1761754199),
(45581, 'Psalms 66:8', 'Psalms', 66, 8, 'د دنیا خلکو، زمونږ خدای وستایئ پرېږدئ ستاینې ستاسې واورېدل شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_8.mp3', '', 1761754199, 1761754199),
(45582, 'Psalms 66:9', 'Psalms', 66, 9, 'مونږ یې ساتلي یو ژوندي نه یې ښویېدلو ته پښې زمونږ پریښې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_9.mp3', '', 1761754199, 1761754199),
(45583, 'Psalms 66:10', 'Psalms', 66, 10, 'مونږ اچولي یو تا په امتحان کې خدایه لکه سپین زر چې شي پاک اور باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_10.mp3', '', 1761754199, 1761754199),
(45584, 'Psalms 66:11', 'Psalms', 66, 11, 'تا مونږ په دام کې ګرفتار کړلو زمونږ په اوږو باندې دې کېښودل درانه بارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_11.mp3', '', 1761754199, 1761754199),
(45585, 'Psalms 66:12', 'Psalms', 66, 12, 'دښمنان دې زمونږ پرېښودل چې پایمال مو کړي تېر شو په اور او په سېلاب کې مونږه اخر دې راوستلو مونږ د پرېمانۍ ځای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_12.mp3', '', 1761754199, 1761754199),
(45586, 'Psalms 66:13', 'Psalms', 66, 13, 'زه به ستا کور ته سوځېدونکې قربانۍ راوړم او د وعدو سره به سم درکړم نذرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_13.mp3', '', 1761754199, 1761754199),
(45587, 'Psalms 66:14', 'Psalms', 66, 14, 'هغه وعدې چې په سختۍ کې مې پرې خلاصې کړلې شونډې خپلې او مې په ژبه باندې راوړلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_14.mp3', '', 1761754199, 1761754199),
(45588, 'Psalms 66:15', 'Psalms', 66, 15, 'زه به چاغ څاروي کړم تاته وړاندې د سوځېدونکو نذرانو په څېر وي به بوی د قربانۍ د پسونو زه نذرانه به کړم غویان او هم وزان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_15.mp3', '', 1761754199, 1761754199),
(45589, 'Psalms 66:16', 'Psalms', 66, 16, 'ای ټولو خلکو چې وېرېږئ له خدای راشئ واورئ زه به خبر کړم تاسو د هغو کارو نه کړي چې هغه زما دپاره دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_16.mp3', '', 1761754199, 1761754199),
(45590, 'Psalms 66:17', 'Psalms', 66, 17, 'وهلې چیغې مې هغه ته د کومک دپاره او زما ژبې د هغه ثنا صفت بیان کړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_17.mp3', '', 1761754199, 1761754199),
(45591, 'Psalms 66:18', 'Psalms', 66, 18, 'که مې په زړه کې ګناهونه خپل ساتلي وای پټ څښتن به نه وای اورېدلې دعاګانې زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_18.mp3', '', 1761754199, 1761754199),
(45592, 'Psalms 66:19', 'Psalms', 66, 19, 'خو په رښتیا خدای اورېدلې دعاګانې زما قبوله کړې یې دعا ده زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_19.mp3', '', 1761754199, 1761754199),
(45593, 'Psalms 66:20', 'Psalms', 66, 20, 'د خدای ثنا وایمه ځکه چې رد کړې یې دعا نه ده زما او زما نه یې نه ده سپمولې خپله تلپاتې مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms66_verse_20.mp3', '', 1761754199, 1761754199),
(45594, 'Ezra 5:1', 'Ezra', 5, 1, 'په هغه وخت کې دوه نبیانو یعنې حجي او د عیدو زوی زکریا د اسراییلو د هغه خدای پیغام چې د ټولو نه اوچت دی، هغو یهودیانو ته ورساوه چې په یهودا او اورشلیم کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_1.mp3', '', 1761754199, 1761754199),
(45595, 'Ezra 5:2', 'Ezra', 5, 2, 'کله چې د شالتي ییل زوی زروبابل او د یوصاداق زوی یشوع د هغوی پیغام واورېد، په اورشلیم کې یې د خدای د کور په بیا ودانولو پیل وکړ او دواړو نبیانو د هغوی سره مرسته وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_2.mp3', '', 1761754199, 1761754199),
(45596, 'Ezra 5:3', 'Ezra', 5, 3, 'تتنای د فرات د سیند د لوېدیځې خوا د ولایت والي، شتار بوزنای او د هغوی ملګري مامورین پرته له ځنډه اورشلیم ته راغلل او پوښتنه یې وکړه: «تاسو ته چا امر کړی دی چې دا کور جوړ کړئ او سرته یې ورسوئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_3.mp3', '', 1761754199, 1761754199),
(45597, 'Ezra 5:4', 'Ezra', 5, 4, 'همدارنګه یې د هغوی نه پوښتنه وکړه: «د هغو سړیو نومونه راکړئ چې د خدای د کور په جوړولو کې مرسته کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_4.mp3', '', 1761754199, 1761754199),
(45598, 'Ezra 5:5', 'Ezra', 5, 5, 'خو خدای د یهودیانو مشران د خپل نظر لاندې ساتل. نو والي او د هغه ډلې پرېکړه وکړه تر هغې چې هغوی داریوش ته رپوټ نه وي ورکړی او ځواب یې نه وي تر لاسه کړی، خلک به نه مجبوروي چې کار ودروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_5.mp3', '', 1761754199, 1761754199),
(45599, 'Ezra 5:6', 'Ezra', 5, 6, 'دا هغه لیک دی چې د فرات د سیند د لوېدیځ ولایت والي تتنای، شتار بوزنای او د هغوی همکارانو داریوش پاچا ته لېږلی ؤ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_6.mp3', '', 1761754199, 1761754199),
(45600, 'Ezra 5:7', 'Ezra', 5, 7, '«ژوندی دې وي داریوش پاچا!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_7.mp3', '', 1761754199, 1761754199),
(45601, 'Ezra 5:8', 'Ezra', 5, 8, 'د پاچا حضور ته دې دا راپور وړاندې شي چې مونږ د یهودا ولایت ته چې د لوی خدای کور په کې دی، لاړو. مونږ ولیدل چې هغه کور د لویو تیږو څخه جوړیږي او د هغه په دېوالونو باندې د لرګیو تیران ایښودل کیږي. دا کار په ډېر غور سره کیږي او د ودانولو کار په ښه ډول په مخ ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_8.mp3', '', 1761754199, 1761754199),
(45602, 'Ezra 5:9', 'Ezra', 5, 9, 'بیا مونږ د قوم د مشرانو نه پوښتنه وکړه: ‹تاسو ته چا امر کړی دی چې دا کور جوړ کړئ او سرته یې ورسوئ؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_9.mp3', '', 1761754199, 1761754199),
(45603, 'Ezra 5:10', 'Ezra', 5, 10, 'همدارنګه مونږ د هغوی د نومونو پوښتنه وکړه، ترڅو وکولای شو د هغو کسانو نومونه ولیکو او تاسو خبر کړو چې هغوی د دوی مشران دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_10.mp3', '', 1761754199, 1761754199),
(45604, 'Ezra 5:11', 'Ezra', 5, 11, 'هغوی ځواب راکړ: ‹مونږ د ځمکې او اسمان د خدای خدمتګاران یو او د هغه هغه کور بېرته جوړوو چې ډېر کلونه مخکې د اسراییلو د لوی پاچا له خوا جوړ شوی او د هغه د جوړولو کار سرته رسېدلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_11.mp3', '', 1761754199, 1761754199),
(45605, 'Ezra 5:12', 'Ezra', 5, 12, 'خو په دې سبب چې زمونږ نیکونو د اسمانونو خدای په قهر کړی ؤ، نو خدای هغوی د بابل پاچا کلداني نبوکدنصر ته تسلیم کړل او هغه دا کور وران کړ او خلک یې د اسیرانو په توګه د بابل هېواد ته بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_12.mp3', '', 1761754199, 1761754199),
(45606, 'Ezra 5:13', 'Ezra', 5, 13, 'خو د بابل پاچا کوروش د خپلې پاچاهۍ په لومړي کال یو فرمان ورکړ چې د خدای دا کور دې بېرته جوړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_13.mp3', '', 1761754199, 1761754199),
(45607, 'Ezra 5:14', 'Ezra', 5, 14, 'د سرو او سپینو زرو هغه لوښي چې نبوکدنصر د اورشلیم د عبادتځای نه وړي وو او هغه یې د بابل د عبادت په ځای کې ایښي وو، کوروش پاچا هغه د هغه ځای نه راوویستل او یو سړي ته یې چې شیشبصر نومېده او کوروش هغه د یهودا د والي په توګه ټاکلی ؤ، وسپارل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_14.mp3', '', 1761754199, 1761754199),
(45608, 'Ezra 5:15', 'Ezra', 5, 15, 'پاچا هغه ته وویل: ”دا لوښي واخله، لاړ شه او په اورشلیم کې یې د خدای په کور کې کېږده. د خدای کور په هماغه پخواني ځای کې بېرته ودان کړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_15.mp3', '', 1761754199, 1761754199),
(45609, 'Ezra 5:16', 'Ezra', 5, 16, 'نو شیشبصر راغی او د خدای د کور بنیاد یې کېښود. له هماغه وخت نه تر اوسه پورې د هغه د جوړولو کار روان دی او تر اوسه لا پای ته نه دی رسېدلی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_16.mp3', '', 1761754199, 1761754199),
(45610, 'Ezra 5:17', 'Ezra', 5, 17, 'نو که ستاسو اعلیحضرت خوښه وي، پرېږدئ چې د بابل شاهي سندونه ولټول شي، ترڅو دا معلوم شي چې کوروش پاچا په رښتیا دا امر کړی ؤ یا نه، چې په اورشلیم کې دې د خدای دا کور بېرته ودان شي. بیا مونږ خبر کړئ چې په دې هکله ستاسو پرېکړه څه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra5_verse_17.mp3', '', 1761754199, 1761754199);